{
  "nl": {
    "issue": [
      {
        "text": "没有法定或者约定义务的人为他人利益管理事务时，无因管理是否成立，管理人享有哪些请求权、负担哪些义务",
        "rules": [
          "c979-1",
          "c979-claim-expenses",
          "c979-claim-compensation",
          "c981-1",
          "c982-1",
          "c983-1"
        ]
      },
      {
        "text": "管理事务不符合受益人真实意思时，管理人的请求权是否被排除",
        "rules": [
          "c979-2",
          "c979-2-exc"
        ]
      },
      {
        "text": "管理事务不属于无因管理但受益人享有管理利益时，受益人如何承担责任",
        "rules": [
          "c980"
        ]
      }
    ],
    "conditions": [
      {
        "text": "管理人没有法定的或者约定的义务，为避免他人利益受损失而管理他人事务",
        "rules": [
          "c979-1"
        ]
      },
      {
        "text": "管理人因管理事务支出了必要费用；或者因管理事务受到损失",
        "rules": [
          "c979-claim-expenses",
          "c979-claim-compensation"
        ]
      },
      {
        "text": "管理事务不符合受益人的真实意思",
        "rules": [
          "c979-2"
        ]
      },
      {
        "text": "受益人的真实意思违反法律或者违背公序良俗",
        "rules": [
          "c979-2-exc"
        ]
      },
      {
        "text": "管理事务不属于第979条规定的情形，但受益人享有管理利益",
        "rules": [
          "c980"
        ]
      },
      {
        "text": "中断管理对受益人不利且无正当理由",
        "rules": [
          "c981-2"
        ]
      },
      {
        "text": "能够通知受益人；管理的事务不需要紧急处理",
        "rules": [
          "c982-1",
          "c982-2"
        ]
      },
      {
        "text": "管理结束；管理人因管理事务取得财产",
        "rules": [
          "c983-1",
          "c983-2"
        ]
      }
    ],
    "exceptions": [
      {
        "text": "管理事务不符合受益人真实意思的，管理人不享有偿还必要费用、适当补偿的请求权",
        "rules": [
          "c979-2"
        ]
      },
      {
        "text": "但受益人的真实意思违反法律或者违背公序良俗的，管理人仍享有第979条第1款的权利",
        "rules": [
          "c979-2-exc"
        ]
      }
    ],
    "effects": [
      {
        "text": "无因管理成立，管理人可以请求受益人偿还因管理事务而支出的必要费用",
        "rules": [
          "c979-1",
          "c979-claim-expenses"
        ]
      },
      {
        "text": "管理人因管理事务受到损失的，可以请求受益人给予适当补偿",
        "rules": [
          "c979-claim-compensation"
        ]
      },
      {
        "text": "受益人应当在其获得的利益范围内向管理人承担第979条第1款规定的义务",
        "rules": [
          "c980"
        ]
      },
      {
        "text": "管理人应当采取有利于受益人的方法管理事务；中断管理对受益人不利的，无正当理由不得中断",
        "rules": [
          "c981-1",
          "c981-2"
        ]
      },
      {
        "text": "能够通知的，管理人应当及时通知受益人；事务不需要紧急处理的，应当等待受益人的指示",
        "rules": [
          "c982-1",
          "c982-2"
        ]
      },
      {
        "text": "管理结束后，管理人应当向受益人报告管理事务的情况，并及时转交因管理事务取得的财产（包括孳息）",
        "rules": [
          "c983-1",
          "c983-2"
        ]
      },
      {
        "text": "管理人无报酬请求权；即使受益人未获益，管理人仍可请求偿还必要费用",
        "rules": [
          "c979-doctrine-noreward",
          "c979-doctrine-nobenefit"
        ]
      },
      {
        "text": "管理人为受益人利益以自己名义负担债务的，有权要求受益人直接向债权人清偿",
        "rules": [
          "c979-doctrine-directpayment"
        ]
      }
    ],
    "priority": [
      {
        "text": "管理事务不符合受益人真实意思的，排除第979条第1款的偿还必要费用请求权与适当补偿请求权",
        "rules": [
          "c979-2"
        ]
      },
      {
        "text": "受益人的真实意思违反法律或者违背公序良俗的，但书优先，不适用第979条第2款的排除",
        "rules": [
          "c979-2-exc"
        ]
      },
      {
        "text": "第980条是第979条的补充规则：不属于无因管理但受益人享有管理利益的，在获益范围内承担第979条第1款义务",
        "rules": [
          "c980"
        ]
      }
    ],
    "distinguish": [
      {
        "text": "LEGO 卡片称第980条“基于不当得利”，与法条不符：第980条是法定的特别规则，直接使受益人在获益范围内承担第979条第1款义务，并非不当得利返还",
        "rules": []
      },
      {
        "text": "笔记将“必要费用”解释为管理或服务活动中直接支出的费用及受到的实际损失，并称一般以本人所受利益范围为限，属学理说明，法条未明文限定",
        "rules": [
          "c979-doctrine-cap"
        ]
      },
      {
        "text": "第981条至第983条是管理人的义务规范，违反可能构成债务不履行，但不影响无因管理的成立与第979条的请求权",
        "rules": []
      },
      {
        "text": "LEGO 卡片把“受益人实际获得管理利益”列为无因管理的成立要件，与第979条不符：获益只是第980条的适用前提，不是第979条的成立要件",
        "rules": [
          "c979-doctrine-nobenefit"
        ]
      }
    ]
  },
